// this seeder generated by artisan

use crate::factories::post_factory::PostFactory;
use crate::seeders::database_seeder::SeederContext;
use crate::seeders::helper::file::find_file;
#[allow(unused_imports)]
use anyhow::{Result, anyhow};
use macros_core::factory::Pawn;
use rand::prelude::SliceRandom;
use rand::rng;
use rustavel_core::helper::number::random;
// model: Post (models live in the app crate and can't be imported here)

pub struct PostSeeder;

impl PostSeeder {
    /**
     * Run the database seeds.
     */
    pub async fn run(ctx: SeederContext) -> Result<bool> {
        let mut images = find_file("storage/app/public/product/", "*").unwrap();
        let sql = r#"INSERT INTO posts (title,slug,body,user_id,image,created_at,updated_at) VALUES
        (?, ?, ?, ?, ?, ?, ?)"#;
        images.shuffle(&mut rng());
        let users = PostFactory::factory().count(70).create();

        for (i, user) in users.into_iter().enumerate() {
            sqlx::query(sql)
                .bind(user.title)
                .bind(user.slug)
                .bind(user.body)
                .bind(random(1, 10))
                .bind(
                    images
                        .get(i % (images.len() - 1))
                        .unwrap()
                        .replace("storage/app/public", "storage"),
                )
                .bind(user.created_at)
                .bind(user.updated_at)
                .execute(&ctx.pool)
                .await?;
        }

        Ok(true)
    }
}
